---StartAnimation
---开启进行动画的操作逻辑
function BlackOverlayMB:StartAnimation()
    if self.isStarted then
        if isNotNull(self.animator) then
            local entryTime = CfUtils.GetAnimatorTime(self.animator, "CommonTransition_Enter")
            local endTime = CfUtils.GetAnimatorTime(self.animator, "CommonTransition_End")
            return entryTime, endTime
        else
            return 0.333, 0.333
        end
    end
    self.isStarted = true
    ---@type Engine.UI.OrderTracker
    local OrderTracker = KTool.GetComponent(self.controller.gameObject, typeof(CS.Engine.UI.OrderTracker))
    if OrderTracker then
        OrderTracker.addSortingOrder = 5000
    end
    KTool.SetActive(self.controller.gameObject, true)

    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    if isNull(self.animator) then
        local canvasImageTrans = self.controller.transform:Find('Root')
        self.animator = KTool.GetComponent(canvasImageTrans.gameObject, typeof(CS.UnityEngine.Animator))
    end
    ---执行动画
    local entryTime = CfUtils.GetAnimatorTime(self.animator, "CommonTransition_Enter")
    local endTime = CfUtils.GetAnimatorTime(self.animator, "CommonTransition_End")

    self._co = cs_coroutine.start(function ()
        xTry(function()
            if self._fadeInCb then
                self._fadeInCb()
            end

            ---End这个触发器只有等到播放loop动画时才起作用，这里等待entryTime是没有必要的
            ---另外这里等待额外导致waitCort代码执行推迟entryTime
            -- cs_coroutine.yield_return(Yielders.GetWaitForSeconds(entryTime))
            if self._waitCort then
                -- printInfo("before cort")
                coroutine.yield(self._waitCort())
                -- printInfo("after cort")
            end


            self.animator:SetBool("End", true)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(endTime))

            if isNotNull(self._endCb) then
                self._endCb()
            end
            -------开始执行关闭的逻辑
            -- printInfo("delete overlay")

            if not KTool.IsNull(self.controller) then
                -- printInfo("delete controller")
                KTool.SafeDelete(self.controller.gameObject)
            end
        end, function()
            if not KTool.IsNull(self.controller) then
                KTool.SafeDelete(self.controller.gameObject)
            end
        end)
    end)
    return entryTime, endTime
end

